<?php
/** Proof — the form (spec "Proof", 1): one ticket (channel form, routed, claimed by the domain), one public message by the requester, one secure link (hash only), one created notice carrying /t/ + 48 hex and nothing of the ticket but the number; a member's address lands on their row; the honeypot; the limits per address and per IP; no CSRF → 403; the form off. */
require __DIR__ . '/lib.php';
$W = world();
q("UPDATE queues SET email_address = 'help@example.invalid' WHERE key = 'general'");
$cat = (int) act(as_member(1), '/settings/vocabulary/category.php', ['name' => 'SMOKE Public cat', 'default_queue' => $W['it'], 'default_priority' => 'high', 'requester_visible' => 'yes'])[1]['record_id'];
echo "1. A submission\n";
$v = visitor();
$r = req('GET', '/request', ['jar' => $v]);
ok($r['code'] === 200 && str_contains($r['body'], 'id="request-form"') && str_contains($r['body'], 'id="request-field-website"') && str_contains($r['body'], 'name="csrf_token"') && !str_contains($r['body'], 'nxl-navigation'), 'GET /request: the form with a honeypot and a CSRF token, no shell');
$txt = need('HD_DEV_STATE') . '/public.txt'; file_put_contents($txt, 'SMOKE public attachment');
$since = last_activity_id();
[$c, $b, $num] = file_request($v, 'Jo2@Customer.invalid', 'SMOKE printer from the form', ['category' => $cat], [$txt]);
ok($c === 200 && $num !== null && preg_match('/^HD-\d{4}$/', $num) === 1 && str_contains($b, 'id="request-done"') && str_contains($b, 'jo2@customer.invalid'), "the thank-you page: the number ($num) and the address as typed");
ok(!str_contains($b, 'printer from the form') && !str_contains($b, '/t/'), 'and nothing else of the ticket — not the subject, not the link');
$t = ticket_by_number($num);
$row = ticket_row($t);
$req = q('SELECT kind, display_name, primary_email::text AS e, organization_id, member_id FROM requesters WHERE id = :r', ['r' => (int) $row['requester_id']])[0];
ok($row['channel'] === 'form' && (int) $row['queue_id'] === $W['it'] && $row['priority'] === 'high' && $row['created_by'] === null && $row['submitter_member_id'] === null, 'the ticket: channel form, routed by the category (IT, high), created_by NULL');
ok($req['kind'] === 'external' && $req['e'] === 'jo2@customer.invalid' && $req['display_name'] === 'SMOKE Visitor' && (int) $req['organization_id'] === $W['org'] && (int) $row['organization_id'] === $W['org'], 'the requester: an external, claimed by Customer Co\'s domain');
$msgs = q('SELECT kind, channel, author_requester_id, author_member_id FROM messages WHERE ticket_id = :t', ['t' => $t]);
ok(count($msgs) === 1 && $msgs[0]['kind'] === 'public_reply' && $msgs[0]['channel'] === 'portal' && (int) $msgs[0]['author_requester_id'] === (int) $row['requester_id'] && $msgs[0]['author_member_id'] === null, 'one public message authored by the requester');
ok((int) one('SELECT count(*) FROM attachments WHERE ticket_id = :t AND message_id IS NOT NULL AND uploaded_by_requester_id = :r', ['t' => $t, 'r' => (int) $row['requester_id']]) === 1, 'the attachment on the message, by the requester');
$links = q('SELECT token_hash, rotated_at FROM ticket_links_secure WHERE ticket_id = :t', ['t' => $t]);
ok(count($links) === 1 && strlen($links[0]['token_hash']) === 64 && $links[0]['rotated_at'] === null, 'one secure link row, its hash only');
$ob = outbox($t, 'created');
ok(count($ob) === 1 && (int) $ob[0]['requester_id'] === (int) $row['requester_id'] && preg_match('#/t/[a-f0-9]{48}#', $ob[0]['body']) === 1 && str_contains($ob[0]['body'], $num) && !str_contains($ob[0]['body'], 'printer from the form'), 'the created notice carries the link and the number, nothing else of the ticket');
ok(hash('sha256', mailed_token($t)) === $links[0]['token_hash'], 'the mailed token is the live link');
$l = activity('ticket.create', $since);
ok(count($l) === 1 && $l[0]['actor_member_id'] === null && (int) $l[0]['actor_requester_id'] === (int) $row['requester_id'] && $l[0]['source'] === 'portal' && json_decode($l[0]['after'], true)['channel'] === 'form' && (int) $l[0]['queue_id'] === $W['it'], 'ticket.create logged with actor_requester_id, source portal, channel form');
$sub = q("SELECT outcome, ticket_id, ip_address::text AS ip FROM request_form_submissions ORDER BY id DESC LIMIT 1")[0];
ok($sub['outcome'] === 'created' && (int) $sub['ticket_id'] === $t && $sub['ip'] !== null, 'the ledger row: created, the ticket, the IP');
echo "2. A member's address, the honeypot, no CSRF\n";
$priyaEmail = (string) one('SELECT email FROM members WHERE id = 26');
$before = (int) one('SELECT count(*) FROM requesters');
[$c, $b, $num2] = file_request($v, $priyaEmail, 'SMOKE Priya by the form');
ok($c === 200 && $num2 !== null && (int) ticket_row(ticket_by_number($num2))['requester_id'] === requester_of_member(26) && (int) one('SELECT count(*) FROM requesters') === $before, 'a member\'s address lands on the member\'s requester row (no second row)');
$n = (int) one('SELECT count(*) FROM tickets');
$since = last_activity_id();
[$c, $b] = public_post($v, '/request', ['name' => 'Bot', 'email' => 'bot@spam.invalid', 'subject' => 'x', 'body' => 'x', 'website' => 'http://spam']);
ok($c === 200 && str_contains($b, 'id="request-done"') && !str_contains($b, 'id="request-done-number"') && (int) one('SELECT count(*) FROM tickets') === $n && q("SELECT outcome FROM request_form_submissions ORDER BY id DESC LIMIT 1")[0]['outcome'] === 'honeypot' && count(activity('request_form.honeypot', $since)) === 1, 'the honeypot filled: the same page, nothing created, outcome honeypot');
[$c, $b] = public_post($v, '/request', ['name' => 'Jo', 'email' => 'jo3@customer.invalid', 'subject' => 'x', 'body' => 'x'], [], false);
ok($c === 403 && (int) one('SELECT count(*) FROM tickets') === $n, 'without the CSRF token: 403');
[$c, $b] = public_post($v, '/request', ['name' => '', 'email' => 'not-an-email', 'subject' => '', 'body' => '']);
ok($c === 422 && str_contains($b, 'id="request-error-name"') && str_contains($b, 'id="request-error-email"') && str_contains($b, 'id="request-form"'), 'validation: the form again with the errors (422)');
echo "3. The limits\n";
$n = (int) one('SELECT count(*) FROM tickets');
for ($i = 1; $i <= 5; $i++) { file_request($v, 'busy@customer.invalid', 'SMOKE busy ' . $i); }
ok((int) one('SELECT count(*) FROM tickets') === $n + 5, 'five from one address in an hour: five tickets');
$since = last_activity_id();
[$c, $b, $num6] = file_request($v, 'busy@customer.invalid', 'SMOKE busy 6');
ok($c === 200 && $num6 === null && str_contains($b, 'id="request-done"') && (int) one('SELECT count(*) FROM tickets') === $n + 5 && q("SELECT outcome FROM request_form_submissions ORDER BY id DESC LIMIT 1")[0]['outcome'] === 'rate_limited' && count(activity('request_form.rate_limited', $since)) === 1, 'the sixth: the same page, nothing created, outcome rate_limited');
ok(!str_contains((string) activity('request_form.rate_limited', $since)[0]['after'], 'busy@'), 'the log never carries the address');
q('UPDATE app_settings SET form_limit_per_ip = 3 WHERE id = 1');
[$c, $b, $num7] = file_request($v, 'fresh@customer.invalid', 'SMOKE fresh');
ok($c === 200 && $num7 === null && q("SELECT outcome FROM request_form_submissions ORDER BY id DESC LIMIT 1")[0]['outcome'] === 'rate_limited', 'past the IP limit: rate_limited for a fresh address too');
q('UPDATE app_settings SET form_limit_per_ip = 20 WHERE id = 1');
echo "4. The form off\n";
q('UPDATE app_settings SET request_form_enabled = false WHERE id = 1');
$r = req('GET', '/request', ['jar' => $v]);
ok($r['code'] === 200 && str_contains($r['body'], 'id="request-closed"') && str_contains($r['body'], 'help@example.invalid') && !str_contains($r['body'], 'id="request-form"'), 'the form off: "taken by email at help@example.invalid"');
[$c, $b] = public_post($v, '/request', ['name' => 'Jo', 'email' => 'jo4@customer.invalid', 'subject' => 'x', 'body' => 'x']);
ok($c === 404, 'and POST 404');
q('UPDATE app_settings SET request_form_enabled = true WHERE id = 1');
q("DELETE FROM request_form_submissions WHERE email LIKE 'busy@%' OR email LIKE 'fresh@%'");
finish();
